import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {VILLAGE_FRAMES,drawVillageLife,villagePose} from '../village-life-art.js';
test('painted village atlas has alpha and every authored source rectangle fits',()=>{const bytes=fs.readFileSync(new URL('../art/village-life-v2.webp',import.meta.url)),w=bytes.readUIntLE(24,3)+1,h=bytes.readUIntLE(27,3)+1;assert.equal(bytes.toString('ascii',0,4),'RIFF');assert.equal(bytes.toString('ascii',12,16),'VP8X');assert.ok(bytes[20]&16);for(const frames of Object.values(VILLAGE_FRAMES)){assert.equal(frames.length,4);for(const[x,y,sw,sh]of frames){assert.ok(x>=0&&y>=0&&x+sw<=w&&y+sh<=h);}}});
test('painted sprites keep feet at baseline, proportional sizes, direction and behavior poses',()=>{for(const lifeKind of ['cat','cow','dog','grass'])for(let pose=0;pose<4;pose++){const calls=[],c=new Proxy({},{get:(_,key)=>(...args)=>calls.push([key,...args]),set:()=>true}),o={lifeKind,xy:[3,4],grass:pose,path:pose===1?[[3,4]]:[],activity:pose===3?'sleeping':pose===2?'resting':'standing',facing:-1};assert.ok(drawVillageLife(c,o,0,{}));const draw=calls.find(a=>a[0]==='drawImage');assert.ok(draw);assert.equal(draw.at(-3)+draw.at(-1),0);assert.ok(draw.at(-2)>0&&draw.at(-1)>0);if(lifeKind!=='grass')assert.ok(calls.some(a=>a[0]==='scale'&&a[1]===-1));}assert.equal(villagePose({lifeKind:'cat',activity:'napping',path:[]},0),3);assert.equal(villagePose({lifeKind:'cow',activity:'grazing',path:[]},0),1);assert.equal(villagePose({lifeKind:'cow',path:[[1,1]]},.4),2);});
test('runtime loads the painted atlas and no longer draws placeholder animals',()=>{const main=fs.readFileSync(new URL('../main.js?v=5.6.0',import.meta.url),'utf8'),renderer=fs.readFileSync(new URL('../renderer.js',import.meta.url),'utf8'),life=fs.readFileSync(new URL('../townlife-art.js',import.meta.url),'utf8');assert.match(main,/gameArtDefinitions\(\)/);const definitions=fs.readFileSync(new URL('../art-definitions.js',import.meta.url),'utf8');assert.match(definitions,/architectureMaterials:'architectural-materials-v4.webp'/);assert.match(definitions,/village:'village-life-v2.webp'/);assert.match(renderer,/drawTownLife\(c,o,this.time,this.assets.village\)/);assert.ok(!life.includes('fillRect'));});
